# THE CELLS OF CHAPTER 19 — F1 the cities of refuge, F2 the landmark and the witnesses; and F3 the priest's speech (20:1-9) (each ask a case; the verdicts DATA rows or PARAMETERS)
# =====================================================================
def the_cities_of_refuge(case, data):
    """F1 — Deut 19:1-13 — TWO LINES: refuge_cities_declared (19:1-3, 7-10) writing three_cities_separated_commanded, way_prepared_commanded, land_divided_in_three_commanded and three_more_cities_conditioned (STATUSES); manslayer_and_murderer_declared (19:4-6, 11-13) writing manslayer_flight_permitted, murderer_extradition_commanded, innocent_blood_purge_commanded (STATUSES) and murderer_pity_barred (a BLOCK); Numbers 35's cells by CALL (refuge), 4:41-43's by CALL (obey_horeb), 12:29's by CALL (place_name), the ox's clock by CALL (ordinances); the cases the manslayer's and the murderer's — their bodies the answer sheet's persons"""
    del P_[:]
    ask = case['ask']
    if ask == 'when_the_lord_cuts_off_the_nations':
        ink('19:1', '"WHEN THE LORD YOUR GOD CUTS OFF THE NATIONS whose land the LORD your God gives you, and you possess them and dwell in their cities and in their houses" — 19:1 restates 12:29\'s opening: %d tokens in order shared (the reading\'s assert), the closest kin %s' % (TWIN['19:1 vs 12:29'], KINC[(19, 1)][0]))
        move('the Sifrei 179:1-2 (read whole at the reading); cold_run_place_name (CALL) — PN.when_the_lord_cuts_off_the_nations = %s' % (PN_CUT[1],), "'WHEN THE LORD CUTS OFF' — 12:29's opening seven words said again: the cutting off is 7:1's dispossession (nations_cut_off_warned on the tape at 12:29-31 THE READBACK'S REFERENCE); 'and you possess them and dwell' — the condition of the cities: after the possession and the dwelling, not before (179:1-2)")
        dat("the opening a DATA row (12:29's twin — the tape's own line the reference, never a second act); the exam's person the community that separates its cities before the possession — accepted as a preparation, the duty falling with the dwelling")
        return out("when the LORD cuts off the nations (19:1) — 12:29's opening said again, %d tokens in order (the Sifrei 179:1-2; place_name's %s by CALL): the cities' duty falls with the possession and the dwelling; the community that separates before the possession accepted" % (TWIN['19:1 vs 12:29'], PN_CUT[1][0]), ['accepted'])
    if ask == 'three_cities_in_the_midst':
        ink('19:2', '"THREE CITIES YOU SHALL SEPARATE FOR YOURSELF in the midst of your land" — the parser %s at 19:2; "separate for yourself" at 19:2 and 19:7 (the reading\'s formula seats); cities_set_apart ONE on israel_people (4:41-43\'s line) THE TAPE\'S REFERENCE' % (PARSE[(19, 2)][0],))
        move('the Sifrei 180:1-4 (read whole at the reading); MISHNAH MAKKOT 2:4 (the exam row, read whole); cold_run_obey_horeb (CALL) — OH.then_moses_set_apart = %s, OH.not_until_all_six = %s; cold_run_refuge (CALL) — RG.six_cities = %s' % (OH_SET[1], OH_SIX[1], RG_SIX[1]), "'IN THE MIDST OF YOUR LAND' — not on its border (180:1); 'three cities' — in the land of Canaan, against the three beyond the Jordan Moses set apart (180:2-3; 4:41-43's line the tape's reference); 'separate for yourself' — one seat for each (180:4); MISHNAH MAKKOT 2:4: the manslayer is exiled to the three beyond the Jordan and the three in Canaan, and the three beyond the Jordan did not admit until the three in the land were chosen — 'six cities of refuge shall they be' (Numbers 35:13), all six admitting as one (refuge's six by CALL; obey_horeb's debit READ OPEN)")
        dat("THE WRITE three_cities_separated_commanded — a STATUS on israel_people at the chapters' own day (DJ2); THE PARAMETER the_six_as_one (Makkot 2:4 — no admission until all six); the exam's person the manslayer who fled to Bezer before the three in Canaan were chosen — exempt from the city's protection until all six (obey_horeb's arm), the case's own body")
        return out("three cities in the midst (19:2) — in the midst, not on the border; three against Moses' three; one seat each; none admits until all six are chosen (the Sifrei 180:1-4; Mishnah Makkot 2:4; obey_horeb's %s and refuge's %s by CALL): THE WRITE three_cities_separated_commanded, a STATUS on Israel at the chapters' own day; the manslayer at Bezer before Canaan's three exempt from its protection" % (OH_SET[1][0], RG_SIX[1][0]), ['three_cities_separated_commanded'])
    if ask == 'the_way_prepared_and_the_border_in_three':
        ink('19:3', '"YOU SHALL PREPARE THE WAY FOR YOURSELF, AND DIVIDE INTO THREE the border of your land which the LORD your God gives you to inherit" — the parser reads "divide into three" as %s at 19:3 (the reading\'s assert); "three" at 19:7 and 19:9 the same word %s, %s' % (PARSE[(19, 3)][0], PARSE[(19, 7)][0], PARSE[(19, 9)][0]))
        move('the Sifrei 180:5-8 (read whole at the reading)', "'PREPARE THE WAY' — the roads made straight, 'refuge, refuge' written at the crossroads (180:5-6; Makkot 10b the English's note, not read); 'DIVIDE INTO THREE THE BORDER' — the three distances equal: from the border to the first as from the first to the second, from the second to the third as from the third to the border (180:7-8) — the parser's [3] a division, not a count of cities")
        dat("THE WRITES way_prepared_commanded and land_divided_in_three_commanded — STATUSES on israel_people at the chapters' own day (DJ2); THE PARAMETER the_three_distances (equal thirds — the answer sheet's geometry from the spine); the exam's person the court that sets the cities at unequal distances — barred from it")
        return out("the way prepared and the border in three (19:3) — the roads straight and marked, the border divided so the three distances are equal (the Sifrei 180:5-8; the parser's %s a division): THE WRITES way_prepared_commanded and land_divided_in_three_commanded, STATUSES on Israel at the chapters' own day; the court that sets the cities at unequal distances barred from it" % (PARSE[(19, 3)][0],), ['way_prepared_commanded', 'land_divided_in_three_commanded'])
    if ask == 'this_is_the_word_of_the_manslayer':
        ink('19:4', '"AND THIS IS THE WORD OF THE MANSLAYER who shall flee there and live" — 19:4 shares %d tokens in order with 4:42 (the reading\'s assert: 4:42 is 19:4\'s words with \'slays\' for \'smites\'); Exodus 21:13\'s "who shall flee there" %d (the shared run)' % (TWIN['19:4 vs 4:42'], TWIN['19:4 vs Exod 21:13']))
        move('the Sifrei 181:1 (read whole at the reading — MISHNAH MAKKOT 2:8 CITED IN THE SPINE\'S OWN HEBREW); cold_run_obey_horeb (CALL) — OH.DATA[the_manslayer_definition] deut_19_4 = %s; cold_run_refuge (CALL) — RG.the_honor = %s' % (OH_MANDEF['value']['deut_19_4'][:40], RG_HONOR[1]), "'THIS IS THE WORD OF THE MANSLAYER' — the manslayer whom the city's men wish to honor says to them 'I am a manslayer'; if they say 'even so', he accepts from them (Makkot 2:8: 'and this is the word of the manslayer'); the rent — R. Judah he pays the Levites, R. Meir he does not; the return — R. Meir he returns to the office he held, R. Judah he does not: TWO ARMS on each, the Mishnah's own row; 'and live' — make life livable, the teacher exiled with his school (4:42's clause — obey_horeb's row by CALL)")
        dat("THE PARAMETER the_manslayers_word (Makkot 2:8 — the honor accepted after the word; the rent and the office each two arms); the exam's person the manslayer honored by the city who said 'I am a manslayer' and was told 'even so' — accepted")
        return out("this is the word of the manslayer (19:4) — 'I am a manslayer', and honored after the word; the rent and the office disputed, two arms each (the Sifrei 181:1 = Mishnah Makkot 2:8, cited in the spine's own Hebrew; obey_horeb's definition and refuge's %s by CALL): the manslayer honored after his word accepted" % (RG_HONOR[1][0],), ['accepted'])
    if ask == 'unknowingly_not_hating_from_yesterday':
        ink('19:4-5', '"who smites his neighbor UNKNOWINGLY, and he hated him not from yesterday and the day before" — "unknowingly" at 19:4 and 4:42 in the Torah, Joshua 20:3, 20:5 and Job 35:16 beyond (the reading\'s formula assert); "FROM YESTERDAY AND THE DAY BEFORE" TWO seats in the Bible — 19:4 and Exodus 21:29 THE GORING OX; the parser %s at 19:5 ("one" of the wood)' % (PARSE[(19, 5)][0],))
        move('the Sifrei 181:2-6, 182:1 (read whole at the reading); cold_run_ordinances (CALL) — OR.courts(enemy_ox) = %s, OR.courts(who_is_enemy) = %s; cold_run_refuge (CALL) — RG.the_intents = %s, RG.the_manners = %s; cold_run_obey_horeb (CALL) — OH.the_manslayer_defined = %s' % (OR_OX[0], OR_WHO[0][:2], RG_INTENTS[1], RG_MANNERS[1], OH_DEF[1]), "'UNKNOWINGLY' — the unwitting killer, not the wilful and not the one near to wilful (181:2-4 — refuge's intents and manners the table by CALL); 'AND HE HATED HIM NOT FROM YESTERDAY AND THE DAY BEFORE' — the clock of prior knowledge one for the hater and for the ox's owner (Exodus 21:29's forewarned ox: the same three days — ordinances by CALL; the hater of three days off the bench and the stand — refuge's not_his_enemy); the hater's flight no flight (182:1)")
        dat("THE WRITE manslayer_flight_permitted — a STATUS on israel_people at the chapters' own day (DJ2); the prior-knowledge clock a DATA row (the ox's three days and the hater's — one clock, two seats); flees_to_refuge 0 and dwells_in_refuge 0 on the running world THE TAPE'S REFERENCES unmoved (no killer on the tape); the exam's person the unwitting killer who hated not — his flight permitted, the case's own body flees_to_refuge")
        return out("unknowingly, not hating from yesterday (19:4-5) — the unwitting killer alone, the hater's clock the goring ox's (the Sifrei 181:2-6, 182:1; ordinances' %s and refuge's %s by CALL; obey_horeb's definition): THE WRITE manslayer_flight_permitted, a STATUS on Israel at the chapters' own day; the unwitting killer's flight permitted" % (OR_OX[0], RG_INTENTS[1][0]), ['manslayer_flight_permitted'])
    if ask == 'the_forest_and_the_ax':
        ink('19:5', '"as one who goes with his neighbor INTO THE FOREST to hew wood, and his hand swings the ax to cut the tree, AND THE IRON SLIPS FROM THE WOOD and finds his neighbor and he dies — he shall flee to one of these cities and live" — the iron of Numbers 35:16 by CALL; the two headless piska\'s rows read whole at the reading (182-183)')
        move('the Sifrei 182:2-183:8 (read whole at the reading); MISHNAH MAKKOT 2:2 (the exam row, read whole); cold_run_refuge (CALL) — RG.the_iron = %s, RG.the_deliverance = %s' % (RG_IRON[1], RG_DELIV[1]), "MISHNAH MAKKOT 2:2: he who threw a stone into the public domain and killed — exiled; R. Eliezer b. Jacob: if after the stone left his hand the other put out his head and received it, exempt; threw into his courtyard and killed — if the victim had permission to enter, exiled, if not, not: 'AS ONE WHO GOES WITH HIS NEIGHBOR INTO THE FOREST' — as the forest is a place where the victim and the killer may both enter, so every place where both may enter; ABBA SHAUL: as the wood-cutting is optional, so everything optional — the father striking his son, the teacher his student, the court's agent EXCLUDED; 'THE IRON SLIPS FROM THE WOOD' — from the handle (Rabbi) or from the wood being split (the sages): TWO ARMS the ledger's own row (183:1-3; Makkot 2:1 the row's seat)")
        dat("THE PARAMETER the_forest_rule (Makkot 2:2 — the place where both may enter; the optional act; the three excluded); THE PARAMETER the_ax_from_the_handle (Rabbi and the sages — two arms); the exam's person the one who threw a stone into the public domain and killed — exiled: flees_to_refuge the case's own body (the tape's 0 unmoved)")
        return out("the forest and the ax (19:5) — the place where both may enter, the optional act, the father and the teacher and the court's agent excluded; the iron from the handle or from the wood, two arms (the Sifrei 182:2-183:8; Mishnah Makkot 2:2; refuge's %s by CALL): the thrower of a stone into the public domain exiled" % (RG_IRON[1][0],), ['flees_to_refuge'])
    if ask == 'the_avengers_hot_heart_and_the_boundary':
        ink('19:6', '"LEST THE AVENGER OF BLOOD PURSUE THE MANSLAYER WHILE HIS HEART IS HOT, and overtake him because the way is long, and smite him mortally, and he had no sentence of death, since he hated him not from yesterday and the day before" — "the avenger of blood" at 19:6, 19:12 and Numbers 35\'s five seats (the reading\'s formula assert); JOSHUA 20:5 the closest kin of 19:6 (%s — the Prophets: the run\'s citation, never a row)' % (KINC[(19, 6)][0],))
