# THE CELLS OF CHAPTERS 20-21 (first half) — F4 the siege (20:10-20), F5 the broken-necked heifer (21:1-9), F6 the captive (21:10-14) (each ask a case; the verdicts DATA rows or PARAMETERS)
# =====================================================================
def the_siege(case, data):
    """F4 — Deut 20:10-20 — THREE LINES: siege_law_declared (20:10-15) writing peace_call_commanded, tribute_service_commanded, siege_males_smitten_commanded, spoil_permitted and far_cities_scope_declared (STATUSES); seven_nations_herem_declared (20:16-18 — herem is the ban) writing nothing_alive_left_commanded (a STATUS) and abominations_teaching_barred (a BLOCK); siege_trees_declared (20:19-20) writing fruit_tree_cutting_barred (a BLOCK) and siege_works_permitted (a STATUS); Sihon's messengers by CALL (opening_speech), Midian's war by CALL (midian), the seven and the ban by CALL (seven_nations), 18:9's learning by CALL (courts_prophet); THE RECEIPT 20:17 a run citation behind (nations_devoted at 7:1)"""
    del P_[:]
    ask = case['ask']
    if ask == 'call_to_it_for_peace':
        ink('20:10', '"WHEN YOU DRAW NEAR TO A CITY TO FIGHT AGAINST IT, YOU SHALL CALL TO IT FOR PEACE" — "and you shall call to it for peace" the Bible\'s one seat (the reading\'s formula assert); "peace" in the book at 20:10, 20:11, 29:18 and 2:26 (Sihon\'s "words of peace" — the reading\'s lemma assert)')
        move('the Sifrei 199:1-5 (read whole at the reading; 199:5 REREAD from chapters 1-3); cold_run_opening_speech (CALL) — OP.the_bypass(sihon_commanded) = %s, (the_speech_resumed) = %s' % (OP_SIHON[1], OP_RESUMED[1]), "'WHEN YOU DRAW NEAR TO A CITY' — the optional war, not the seven nations' (199:1-4: the peace call's scope); GREAT IS PEACE — even in war the call first; Sihon's messengers: Deuteronomy 2:26's 'words of peace' retells Numbers 21:21's act (the tape's messengers_sent_to_sihon at Numbers 21:21-22 and sihon_war_commanded at 2:24-25 THE READBACK'S REFERENCES — opening_speech by CALL); the call three days before (199:5 — the English's note)")
        dat("THE WRITE peace_call_commanded — a STATUS on israel_people at the chapters' own day (DJ2); THE PARAMETER the_peace_calls_scope (199:1-4 — the optional war; the seven by 20:15-16's exception disputed); the exam's person the commander who besieges a far city without the call — barred from it")
        return out("call to it for peace (20:10) — the call first, great is peace; Sihon's messengers the tape's own act (the Sifrei 199:1-5; opening_speech's %s by CALL): THE WRITE peace_call_commanded, a STATUS on Israel at the chapters' own day; the commander who besieges without the call barred from it" % (OP_SIHON[1][0],), ['peace_call_commanded'])
    if ask == 'tribute_and_servitude_both':
        ink('20:11', '"AND IF IT ANSWERS YOU PEACE and opens to you, then all the people found in it SHALL BE TRIBUTARY TO YOU AND SERVE YOU" — "tributary and serve you" the Bible\'s one seat (the reading\'s formula assert); the tribute of Numbers 31:28 a different noun (the levy on the spoil)')
        move('the Sifrei 200:1-3 (read whole at the reading); cold_run_midian (CALL) — MD.the_division(tribute_rate) = %s' % (MD_RATE[1],), "'TRIBUTARY AND SERVE YOU' — both: if they accept the tribute and not the servitude, or the servitude and not the tribute, do not hearken to them until they accept both (200:1-2); Solomon's levy of the remaining nations (1 Kings 9:21 — the Prophets' run citation ahead; 200:3); Numbers 31:28's 'tribute' one of five hundred on the spoil — a different noun and a different thing (midian by CALL: the two tributes a DATA row)")
        dat("THE WRITE tribute_service_commanded — a STATUS on israel_people at the chapters' own day (DJ2); the two tributes a DATA row (the city's and the spoil's); the exam's person the city that accepts the tribute and refuses the servitude — not hearkened to: barred from the peace")
        return out("tribute and servitude both (20:11) — neither without the other; Solomon's levy ahead; the spoil's tribute a different noun (the Sifrei 200:1-3; midian's %s by CALL): THE WRITE tribute_service_commanded, a STATUS on Israel at the chapters' own day; the city that accepts one without the other barred from the peace" % (MD_RATE[1][0],), ['tribute_service_commanded'])
    if ask == 'the_siege_and_the_males':
        ink('20:12-14', '"AND IF IT WILL NOT MAKE PEACE WITH YOU BUT MAKE WAR against you, then you shall besiege it; and when the LORD your God gives it into your hand, YOU SHALL SMITE EVERY MALE OF IT by the edge of the sword; ONLY THE WOMEN AND THE LITTLE ONES and the cattle and all that is in the city, all its spoil, YOU SHALL TAKE AS PLUNDER for yourself, and you shall eat the spoil of your enemies" — "smite every male of it" the Bible\'s one seat; "the women and the little ones" at 20:14 and 3:6 (the reading\'s formula assert); taken_captive THREE and spoil_taken TWO THE TAPE\'S REFERENCES (Numbers 31:9-12\'s line the readback\'s)')
        move('the Sifrei 200:4-7, 201:1-2 (read whole at the reading); cold_run_midian (CALL) — MD.the_war(every_male) = %s, (captives) = %s, (spoil) = %s, MD.the_sentence(every_female_kept) = %s, (deuteronomy_20) = %s' % (MD_MALE[1], MD_CAPT[1], MD_SPOIL[1], MD_FEMALE[1], MD_D20[1]), "'IF IT WILL NOT MAKE PEACE BUT WAR' — even then, the call was owed (200:4); 'WHEN THE LORD GIVES IT INTO YOUR HAND' — the siege's end His, not the sword's (200:5); 'SMITE EVERY MALE' — the males, not the women and the little ones (200:6-7); 'ONLY THE WOMEN AND THE LITTLE ONES' — Numbers 31:17's 'every male among the little ones' STRICTER than this chapter (midian's own ask deuteronomy_20 read at the callees: 'spares the women and the little ones — this chapter stricter on both; NOT COMPILED, owed at its chapter' — PAID HERE); 'YOU SHALL EAT THE SPOIL' — the spoil permitted (201:1-2)")
        dat("THE WRITES siege_males_smitten_commanded and spoil_permitted — STATUSES on israel_people at the chapters' own day (DJ2; spoil_taken and taken_captive the tape's acts, not this status); the exam's person the soldier who spares the men of a far city taken by siege — barred from it; the one who takes its women captive and its cattle as spoil accepted")
        return out("the siege and the males (20:12-14) — even the warring city was owed the call; the LORD ends the siege; the males smitten, the women and the little ones spared, the spoil eaten — Numbers 31's stricter sentence its own chapter's (the Sifrei 200:4-201:2; midian's %s, %s and %s by CALL, its ask deuteronomy_20 paid here): THE WRITES siege_males_smitten_commanded and spoil_permitted, STATUSES on Israel at the chapters' own day; the soldier who spares the men barred from it" % (MD_MALE[1][0], MD_CAPT[1][0], MD_SPOIL[1][0]), ['siege_males_smitten_commanded', 'spoil_permitted'])
    if ask == 'houses_full_of_every_good_thing':
        ink('20:14', '"and you shall eat THE SPOIL OF YOUR ENEMIES which the LORD your God has given you" — 6:11\'s "houses full of every good thing" the spine\'s reread (201:3); the spoil\'s lemma in the book at 20:14 twice and 2:35, 3:7, 13:17 (the reading\'s lemma assert)')
        move('the Sifrei 201:3 (REREAD from chapter 6)', "'THE SPOIL OF YOUR ENEMIES' — even the swine's flesh and the forbidden foods found in the houses are permitted in the war (Chullin 17a — the English's note, not read); 6:11's 'houses full of every good thing which you did not fill' the same permission at the entry (201:3 — the ink names the verse: a REFERENCE without an edge, the cell's ask not on the shelf of asks the recon lists)")
        dat("the spoil's permission a DATA row citing 6:11 (a reference without an edge — no link of our own); the exam's person the soldier who eats forbidden food from the conquered houses in the war — accepted")
        return out("houses full of every good thing (20:14 with 6:11) — the spoil permitted even to the forbidden foods in the war (the Sifrei 201:3, rereading 6:11; Chullin 17a the note): the soldier who eats of the conquered houses in the war accepted", ['accepted'])
    if ask == 'the_far_cities_and_the_seven':
        ink('20:15-16', '"THUS YOU SHALL DO TO ALL THE CITIES VERY FAR FROM YOU, WHICH ARE NOT OF THE CITIES OF THESE NATIONS; ONLY of the cities of these peoples which the LORD your God gives you for an inheritance YOU SHALL LET NO BREATH LIVE" — "you shall let no breath live" the Bible\'s one seat (the reading\'s formula assert); the negations %s, %s' % (NEG[(20, 15)], NEG[(20, 16)]))
        move('the Sifrei 201:4, 202:1-2 (read whole at the reading); cold_run_seven_nations (CALL) — SN.the_bans_condition = %s' % (SN_COND[1],), "'ALL THE CITIES VERY FAR FROM YOU' — the far cities against the seven: the peace call and the tribute theirs, the ban the seven's (201:4); THE PENITENT NATIONS — the Gibeonites who came, and Joshua's three letters before the entry: who wishes to flee, who wishes to make peace, who wishes to make war (202:1-2 — the Jerusalem Talmud's Sheviit, the English's note, not read; seven_nations' the_bans_condition by CALL: the Canaanite who repents is not devoted — 'exempt')")
        dat("THE WRITE far_cities_scope_declared — a STATUS on israel_people at the chapters' own day (DJ2); THE PARAMETER the_far_cities (the peace and the tribute the far cities'; the ban the seven's); THE DATA ROW the_penitent_nations (Joshua's letters — the Prophets' run citation); the exam's person the Gibeonite who made peace before the war — exempt from the ban (seven_nations' arm)")
        return out("the far cities and the seven (20:15-16) — the far cities' peace and tribute, the seven's ban; the penitent nation accepted, Joshua's letters (the Sifrei 201:4, 202:1-2; seven_nations' %s by CALL): THE WRITE far_cities_scope_declared, a STATUS on Israel at the chapters' own day; the Gibeonite who made peace exempt from the ban" % (SN_COND[1][0],), ['far_cities_scope_declared'])
    if ask == 'no_breath_left_alive':
        ink('20:16-17', '"YOU SHALL LET NO BREATH LIVE; BUT YOU SHALL UTTERLY DEVOTE THEM: the Hittite and the Amorite, the Canaanite and the Perizzite, the Hivite and the Jebusite, AS THE LORD YOUR GOD COMMANDED YOU" — SIX named (the Girgashite absent here; the seven at 7:1 — the reading\'s find); "the Hittite and the Amorite" 20:17\'s Torah seat alone, Joshua 9:1 the closest kin (%d tokens in order shared — the Prophets); "utterly devote" the doubled verb the Bible\'s one seat; THE RECEIPT "as the LORD your God commanded you" — the register\'s one seat in the three chapters (good_land\'s receipt_seats(20) = %s)' % (TWIN['20:17 vs Josh 9:1'], GL_R[1]))
        move('the Sifrei 201:5-202:3 (read whole at the reading); cold_run_seven_nations (CALL) — SN.the_seven_nations(the_seven) = %s, (the_ban) = %s; cold_run_good_land (CALL) — the receipt seat %s' % (SN_SEVEN[1], SN_BAN[1], GL_R[1]), "'YOU SHALL LET NO BREATH LIVE' — the ban's form on the seven (201:5); 'UTTERLY DEVOTE THEM' — the six named and the seventh by 7:1 (seven_nations' seven by CALL — the Girgashite the seventh counted by its own verse); 'AS THE LORD YOUR GOD COMMANDED YOU' — THE RECEIPT: Deuteronomy 7:1-5's line nations_devoted BEHIND on the tape — a RUN CITATION (the pointer's form); the register's class NONE on file retyped at the tail to the class the world says (the register gate's own print); the ban's debit on Israel open to Joshua (seven_nations' row: nations_driven_out 0 and city_devoted 0 on the running world — the acts ahead)")
        dat("THE WRITE nothing_alive_left_commanded — a STATUS on israel_people at the chapters' own day (DJ2); THE RECEIPT 20:17 a DATA row (the referent 7:1-5's line behind; the register's disposition at the tail); the exam's person the soldier who leaves a Hittite of a Canaanite city alive under the ban — barred from it")
        return out("no breath left alive (20:16-17) — the ban on the six named and the seventh of 7:1; 'as He commanded you' the receipt of 7:1-5's line behind, a run citation (the Sifrei 201:5-202:3; seven_nations' %s and %s by CALL; good_land's seat %s): THE WRITE nothing_alive_left_commanded, a STATUS on Israel at the chapters' own day; the soldier who leaves a Hittite alive under the ban barred from it" % (SN_SEVEN[1][0], SN_BAN[1][0], GL_R[1]), ['nothing_alive_left_commanded'])
    if ask == 'that_they_teach_you_not':
        ink('20:18', '"SO THAT THEY TEACH YOU NOT TO DO according to all their abominations which they have done for their gods, and you sin against the LORD your God" — "so that they teach you not" the Bible\'s one seat (the reading\'s formula assert); abominations_learning_barred ONE on israel_people (18:9\'s line) THE TAPE\'S REFERENCE')
        move('the Sifrei 202:4 (read whole at the reading); cold_run_courts_prophet (CALL) — CP.learn_to_understand_not_to_do = %s; cold_run_seven_nations (CALL) — SN.abomination_to_the_lord = %s' % (CP_LEARN[1], SN_ABOM[1]), "'SO THAT THEY TEACH YOU NOT' — the reason of the ban: if they repent and are accepted, they are not killed (202:4 — Sotah 8:1's 'against your enemies' the war's scope; the penitent nation accepted); 18:9's 'you shall not learn to do' the learner's block, this the teacher's (courts_prophet by CALL: to understand you may, to do you may not); 'their abominations for their gods' — 7:25-26's abomination to the LORD (seven_nations by CALL)")
        dat("THE WRITE abominations_teaching_barred — a BLOCK on israel_people at the chapters' own day (DJ2 — the teaching's block beside 18:9's learning's, never a second write of that); the exam's person the Canaanite kept alive who teaches his rite — barred from it")
        return out("that they teach you not (20:18) — the ban's reason; the penitent not killed; the teacher's block beside 18:9's learner's (the Sifrei 202:4; courts_prophet's %s and seven_nations' %s by CALL): THE WRITE abominations_teaching_barred, a BLOCK on Israel at the chapters' own day; the Canaanite who teaches his rite barred from it" % (CP_LEARN[1][0], SN_ABOM[1][0]), ['abominations_teaching_barred'])
